"use client";

import React, { useState, useEffect, useRef } from "react";
import { useRouter } from "next/router";

export default function PythonTest() {
  const router = useRouter();

  const [step, setStep] = useState("loading");
  const [timer, setTimer] = useState(20 * 60);
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [tabCount, setTabCount] = useState(0);
  const [autoSubmitReason, setAutoSubmitReason] = useState("");

  const submittedRef = useRef(false);

  /* ---------------- FETCH PYTHON QUESTIONS ---------------- */
  useEffect(() => {
    if (router.query.start === "true") {
      fetch(`/api/getQuestions?category=python`)
        .then(res => res.json())
        .then(data => {
          if (!data || data.length === 0) {
            alert("No Python questions found in database.");
            router.push("/");
            return;
          }
          setQuestions(data);
          setStep("test");
        })
        .catch(() => {
          alert("Error loading questions.");
          router.push("/");
        });
    }
  }, [router.query.start]);

  /* ---------------- TIMER ---------------- */
  useEffect(() => {
    if (step !== "test") return;

    const interval = setInterval(() => {
      setTimer(prev => {
        if (prev <= 1) {
          triggerAutoSubmit(
            "The exam time has ended, so the test was automatically submitted. Kindly contact HR."
          );
          clearInterval(interval);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [step]);

  /* ---------------- SECURITY ---------------- */
  useEffect(() => {
    if (step !== "test") return;

    const block = e => e.preventDefault();
    const blockKeys = e => {
      if (
        e.key === "F12" ||
        (e.ctrlKey && e.shiftKey && ["I", "J", "C"].includes(e.key)) ||
        (e.ctrlKey && e.key === "U")
      ) {
        triggerAutoSubmit(
          "You violated the exam rules, so the test was automatically submitted. Kindly contact HR."
        );
      }
    };

    document.addEventListener("contextmenu", block);
    document.addEventListener("copy", block);
    document.addEventListener("cut", block);
    document.addEventListener("paste", block);
    document.addEventListener("keydown", blockKeys);

    return () => {
      document.removeEventListener("contextmenu", block);
      document.removeEventListener("copy", block);
      document.removeEventListener("cut", block);
      document.removeEventListener("paste", block);
      document.removeEventListener("keydown", blockKeys);
    };
  }, [step]);

  /* ---------------- TAB SWITCH DETECTION ---------------- */
  useEffect(() => {
    if (step !== "test") return;

    const handleVisibility = () => {
      if (document.visibilityState === "hidden") {
        setTabCount(prev => {
          const count = prev + 1;

          if (count === 1 || count === 2) {
            alert(`Warning ${count}/3: Tab switching is not allowed.`);
          }

          if (count >= 3) {
            triggerAutoSubmit(
              "You violated the rules 3 times, so the test was automatically submitted. Kindly contact HR."
            );
          }

          return count;
        });
      }
    };

    document.addEventListener("visibilitychange", handleVisibility);
    return () =>
      document.removeEventListener("visibilitychange", handleVisibility);
  }, [step]);

  /* ---------------- AUTO SUBMIT ---------------- */
  const triggerAutoSubmit = message => {
    if (submittedRef.current) return;
    submittedRef.current = true;
    setAutoSubmitReason(message);
    submitTest(true);
  };

  /* ---------------- SUBMIT ---------------- */
  const submitTest = async (forced = false) => {
  const studentId = localStorage.getItem("studentId");

  await fetch("/api/saveResult", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      studentId,
      answers,
      questions,
      category: "python",
    }),
  });

  setStep("submitted");
};


  const minutes = String(Math.floor(timer / 60)).padStart(2, "0");
  const seconds = String(timer % 60).padStart(2, "0");

  if (step === "submitted") {
    return (
      <CenteredCard title="Python Test Submitted">
        <p className="text-red-600 text-center mb-4 font-semibold">
          {autoSubmitReason || "Your test has been submitted successfully."}
        </p>
        <button
          onClick={() => router.push("/")}
          className="w-full bg-blue-600 text-white py-2 rounded"
        >
          OK
        </button>
      </CenteredCard>
    );
  }

  if (step === "loading") {
    return (
      <CenteredCard title="Loading Python Questions...">
        <p className="text-center">Please wait...</p>
      </CenteredCard>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 px-3 py-4 select-none">
      <div className="sticky top-0 bg-white shadow rounded-xl px-4 py-3 flex justify-between">
        <h2 className="font-bold">Python Test</h2>
        <span className="text-red-600 font-bold">⏱ {minutes}:{seconds}</span>
      </div>

      <div className="max-w-3xl mx-auto mt-4">
        {questions.map((q, i) => (
          <div key={q.id} className="bg-white p-4 rounded-xl shadow mb-4">
            <p className="font-semibold mb-3">{i + 1}. {q.question}</p>
            {[q.option1, q.option2, q.option3, q.option4].map(opt => (
              <button
                key={opt}
                onClick={() => setAnswers(p => ({ ...p, [q.id]: opt }))}
                className={`w-full text-left px-4 py-2 mb-2 rounded border ${
                  answers[q.id] === opt ? "bg-blue-600 text-white" : "bg-white"
                }`}
              >
                {opt}
              </button>
            ))}
          </div>
        ))}

        <button
          onClick={() => submitTest()}
          className="w-full bg-green-600 text-white py-3 rounded-xl font-bold"
        >
          Submit Python Test
        </button>
      </div>
    </div>
  );
}

const CenteredCard = ({ title, children }) => (
  <div className="min-h-screen flex items-center justify-center bg-gray-100 px-3">
    <div className="bg-white p-6 rounded-xl shadow w-full max-w-lg">
      <h2 className="text-xl font-bold text-center mb-4">{title}</h2>
      {children}
    </div>
  </div>
);